    .motion-control[data-paused="true"] .motion-icon { width: 0; height: 0; border: 6px solid transparent; border-right: 0; border-left: 9px solid currentColor; }
    .sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; border: 0; }
    .work { display: grid; grid-template-columns: 1fr 2fr; column-gap: 48px; padding-block: 92px 84px; }
    h2 { margin: 7px 0 30px; font-size: 15px; line-height: 1.5; font-weight: 500; }
